ALTER TABLE public.locales ADD COLUMN codigo_cliente bigint GENERATED BY DEFAULT AS IDENTITY;
CREATE UNIQUE INDEX locales_codigo_cliente_uq ON public.locales(codigo_cliente);
CREATE SEQUENCE public.albaran_numero_seq;
CREATE OR REPLACE FUNCTION public.numerar_albaran() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE codigo bigint;
BEGIN
 SELECT codigo_cliente INTO codigo FROM public.locales WHERE id=NEW.local_id;
 IF codigo IS NULL THEN RAISE EXCEPTION 'Cliente no válido'; END IF;
 NEW.id := 'MHL-' || lpad(codigo::text,4,'0') || '-' || lpad(nextval('public.albaran_numero_seq')::text,6,'0');
 NEW.total := 0; NEW.estado := 'pendiente'; NEW.fecha_pago := NULL;
 RETURN NEW;
END; $$;
CREATE TRIGGER numeracion_albaranes BEFORE INSERT ON public.albaranes FOR EACH ROW EXECUTE FUNCTION public.numerar_albaran();
CREATE TABLE public.pagos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), albaran_id text NOT NULL REFERENCES public.albaranes(id), usuario_id uuid, importe numeric(12,2) NOT NULL, metodo text NOT NULL, fecha timestamptz NOT NULL DEFAULT now(), nombre text NOT NULL DEFAULT '', firma text NOT NULL DEFAULT '', solicitud uuid UNIQUE, historico boolean NOT NULL DEFAULT false,
 CONSTRAINT pago_positivo CHECK(importe > 0), CONSTRAINT metodo_valido CHECK(metodo IN ('efectivo','tarjeta','bizum','sin_clasificar'))
);
GRANT SELECT ON public.pagos TO authenticated;
GRANT ALL ON public.pagos TO service_role;
ALTER TABLE public.pagos ENABLE ROW LEVEL SECURITY;
CREATE POLICY leer_pagos ON public.pagos FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'comercial') AND usuario_id=auth.uid() AND (fecha AT TIME ZONE 'Europe/Madrid')::date=(now() AT TIME ZONE 'Europe/Madrid')::date));
CREATE INDEX pagos_fecha_usuario ON public.pagos(fecha,usuario_id);
CREATE TABLE public.cierres_caja (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL, dia date NOT NULL, creado_por uuid NOT NULL, fecha timestamptz NOT NULL DEFAULT now(), esperado_efectivo numeric(12,2) NOT NULL, esperado_tarjeta numeric(12,2) NOT NULL, esperado_bizum numeric(12,2) NOT NULL, real_efectivo numeric(12,2) NOT NULL, real_tarjeta numeric(12,2) NOT NULL, real_bizum numeric(12,2) NOT NULL, notas text NOT NULL DEFAULT '', UNIQUE(usuario_id,dia), CHECK(real_efectivo>=0 AND real_tarjeta>=0 AND real_bizum>=0)
);
GRANT SELECT ON public.cierres_caja TO authenticated;
GRANT ALL ON public.cierres_caja TO service_role;
ALTER TABLE public.cierres_caja ENABLE ROW LEVEL SECURITY;
CREATE POLICY leer_cierres ON public.cierres_caja FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'comercial') AND usuario_id=auth.uid() AND dia=(now() AT TIME ZONE 'Europe/Madrid')::date));
INSERT INTO public.pagos(albaran_id,importe,metodo,fecha,nombre,firma,usuario_id,historico)
SELECT a.id,a.total,'sin_clasificar',coalesce(a.fecha_pago,a.fecha),a.cobrado_por,a.firma_cobro,
 (SELECT p.id FROM public.profiles p WHERE trim(p.nombre || ' ' || p.apellidos) <> '' AND a.cobrado_por=trim(p.nombre || ' ' || p.apellidos) || ' · CAMINODESANTIAGOLOTERIA · Administración Nº 8 - Ferrol' LIMIT 1),true
FROM public.albaranes a WHERE a.total>0;
UPDATE public.albaranes SET lineas=(SELECT coalesce(jsonb_agg(l || jsonb_build_object('pagados',0)),'[]'::jsonb) FROM jsonb_array_elements(lineas) l) WHERE estado='pendiente';
UPDATE public.albaranes SET estado=CASE WHEN total >= (SELECT coalesce(sum(((l->>'cantidad')::numeric-(l->>'devueltos')::numeric)*20),0) FROM jsonb_array_elements(lineas) l) THEN 'pagado' ELSE 'parcial' END WHERE total>0;
REVOKE UPDATE ON public.albaranes FROM authenticated;
CREATE OR REPLACE FUNCTION public.registrar_cobro(p_id text,p_lineas jsonb,p_importe numeric,p_metodo text,p_firma text,p_solicitud uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE a public.albaranes%ROWTYPE; l jsonb; old jsonb; idx integer; delta integer; ret integer; stock public.decimos%ROWTYPE; nombre_usuario text; debido numeric; cantidad integer; pag integer; dev integer;
BEGIN
 IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'comercial')) THEN RAISE EXCEPTION 'Sin permiso'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text));
 IF EXISTS(SELECT 1 FROM public.pagos WHERE solicitud=p_solicitud AND usuario_id=auth.uid()) THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM public.cierres_caja WHERE usuario_id=auth.uid() AND dia=(now() AT TIME ZONE 'Europe/Madrid')::date) THEN RAISE EXCEPTION 'Tu caja de hoy ya está cerrada'; END IF;
 SELECT * INTO a FROM public.albaranes WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Albarán no encontrado'; END IF;
 IF p_metodo NOT IN ('efectivo','tarjeta','bizum') OR p_importe<=0 OR p_importe<>round(p_importe,2) OR length(p_firma)<20 THEN RAISE EXCEPTION 'Importe, método o firma no válido'; END IF;
 SELECT trim(nombre || ' ' || apellidos) INTO nombre_usuario FROM public.profiles WHERE id=auth.uid();
 IF coalesce(nombre_usuario,'')='' THEN RAISE EXCEPTION 'Completa tu nombre y apellidos antes de cobrar'; END IF;
 nombre_usuario := nombre_usuario || ' · CAMINODESANTIAGOLOTERIA · Administración Nº 8 - Ferrol';
 IF jsonb_typeof(p_lineas)<>'array' OR jsonb_array_length(p_lineas)<>jsonb_array_length(a.lineas) THEN RAISE EXCEPTION 'Líneas no válidas'; END IF;
 debido := 0;
 FOR l,idx IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(p_lineas) WITH ORDINALITY LOOP
  old:=a.lineas->idx; cantidad:=(old->>'cantidad')::integer; pag:=(l->>'pagados')::integer; dev:=(l->>'devueltos')::integer;
  IF l->>'numero' IS DISTINCT FROM old->>'numero' OR l->>'serie' IS DISTINCT FROM old->>'serie' OR l->>'fraccion' IS DISTINCT FROM old->>'fraccion' OR (l->>'cantidad')::integer<>cantidad OR pag IS NULL OR dev IS NULL OR pag<(old->>'pagados')::integer OR dev<(old->>'devueltos')::integer OR pag+dev>cantidad THEN RAISE EXCEPTION 'Cantidades no válidas'; END IF;
  debido:=debido+(cantidad-dev)*20;
 END LOOP;
 IF a.total+p_importe>debido THEN RAISE EXCEPTION 'El importe supera el pendiente de cobro'; END IF;
 FOR l,idx IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(p_lineas) WITH ORDINALITY LOOP
  old:=a.lineas->idx; delta:=(l->>'pagados')::integer+(l->>'devueltos')::integer-(old->>'pagados')::integer-(old->>'devueltos')::integer; ret:=(l->>'devueltos')::integer-(old->>'devueltos')::integer;
  IF delta>0 THEN
   SELECT * INTO stock FROM public.decimos WHERE numero=l->>'numero' AND serie=l->>'serie' AND fraccion=l->>'fraccion' AND ubicacion=a.local_id ORDER BY id LIMIT 1 FOR UPDATE;
   IF NOT FOUND OR stock.cantidad<delta THEN RAISE EXCEPTION 'Stock insuficiente para liquidar esta línea'; END IF;
   UPDATE public.decimos SET cantidad=cantidad-delta WHERE id=stock.id;
   IF ret>0 THEN INSERT INTO public.decimos(id,numero,serie,fraccion,cantidad,ubicacion,estado) VALUES(gen_random_uuid()::text,l->>'numero',l->>'serie',l->>'fraccion',ret,'central','venta'); END IF;
  END IF;
 END LOOP;
 INSERT INTO public.pagos(albaran_id,usuario_id,importe,metodo,nombre,firma,solicitud) VALUES(p_id,auth.uid(),p_importe,p_metodo,nombre_usuario,p_firma,p_solicitud);
 UPDATE public.albaranes SET lineas=p_lineas,total=total+p_importe,estado=CASE WHEN total+p_importe>=debido THEN 'pagado' ELSE 'parcial' END,fecha_pago=now(),cobrado_por=nombre_usuario,firma_cobro=p_firma WHERE id=p_id;
END; $$;
REVOKE ALL ON FUNCTION public.registrar_cobro(text,jsonb,numeric,text,text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.registrar_cobro(text,jsonb,numeric,text,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cerrar_caja(p_usuario uuid,p_dia date,p_efectivo numeric,p_tarjeta numeric,p_bizum numeric,p_notas text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ef numeric; ta numeric; bi numeric;
BEGIN
 IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'comercial') AND p_usuario=auth.uid() AND p_dia=(now() AT TIME ZONE 'Europe/Madrid')::date)) THEN RAISE EXCEPTION 'Sin permiso para cerrar esta caja'; END IF;
 IF p_dia>(now() AT TIME ZONE 'Europe/Madrid')::date OR NOT (public.has_role(p_usuario,'admin') OR public.has_role(p_usuario,'comercial')) OR least(p_efectivo,p_tarjeta,p_bizum)<0 THEN RAISE EXCEPTION 'Datos de cierre no válidos'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(p_usuario::text));
 SELECT coalesce(sum(importe) FILTER(WHERE metodo='efectivo'),0),coalesce(sum(importe) FILTER(WHERE metodo='tarjeta'),0),coalesce(sum(importe) FILTER(WHERE metodo='bizum'),0) INTO ef,ta,bi FROM public.pagos WHERE usuario_id=p_usuario AND (fecha AT TIME ZONE 'Europe/Madrid')::date=p_dia;
 INSERT INTO public.cierres_caja(usuario_id,dia,creado_por,esperado_efectivo,esperado_tarjeta,esperado_bizum,real_efectivo,real_tarjeta,real_bizum,notas) VALUES(p_usuario,p_dia,auth.uid(),ef,ta,bi,p_efectivo,p_tarjeta,p_bizum,p_notas);
END; $$;
REVOKE ALL ON FUNCTION public.cerrar_caja(uuid,date,numeric,numeric,numeric,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cerrar_caja(uuid,date,numeric,numeric,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.leer_copia_albaran(p_hash text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object('id',a.id,'fecha',a.fecha,'estado',a.estado,'tipo',a.tipo,'lineas',a.lineas,'total',a.total,'fechaPago',a.fecha_pago,'receptorNombre',a.receptor_nombre,'firma',a.firma,'cobradoPor',a.cobrado_por,'firmaCobro',a.firma_cobro,'localNombre',l.nombre,'localDireccion',l.direccion,'localTelefono',l.telefono,'codigoCliente',l.codigo_cliente,'receptorDni',a.receptor_dni)
 FROM public.albaran_copias c JOIN public.albaranes a ON a.id=c.albaran_id JOIN public.locales l ON l.id=a.local_id WHERE c.token_hash=p_hash AND c.expires_at>now() AND length(p_hash)=64 LIMIT 1;
$$;